mapper.select:
select rc.class_idx as class_idx, nvl(round(avg(rc.rating), 1), 0) as avg_rating, nvl(count(*), 0) as review_count from review_class rc where rc.class_idx in
#{id}
group by rc.class_idx

mapper.update:
UPDATE USERS
SET STATUS = #{status}
WHERE USER_IDX = #{userIdx}

mapper.select:
SELECT COUNT(*)
FROM CERT
WHERE USER_IDX = #{userIdx}
AND CERT_TYPE = #{certType}
